CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, applied_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS workspaces (id VARCHAR(36) PRIMARY KEY, slug VARCHAR(191) NOT NULL UNIQUE, name VARCHAR(255) NOT NULL, description TEXT NOT NULL DEFAULT '', created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS projects (id VARCHAR(36) PRIMARY KEY, workspace_id VARCHAR(36) NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, external_id VARCHAR(191) NULL, slug VARCHAR(191) NOT NULL, name VARCHAR(255) NOT NULL, description TEXT NOT NULL DEFAULT '', auto_created BOOLEAN NOT NULL DEFAULT FALSE, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL, UNIQUE(workspace_id,slug));
CREATE UNIQUE INDEX IF NOT EXISTS idx_projects_workspace_external_id ON projects(workspace_id,external_id) WHERE external_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS skills (id VARCHAR(36) PRIMARY KEY, workspace_id VARCHAR(36) NULL REFERENCES workspaces(id), project_id VARCHAR(36) NULL REFERENCES projects(id), slug VARCHAR(191) NOT NULL, name VARCHAR(255) NOT NULL, description TEXT NOT NULL DEFAULT '', purpose TEXT NOT NULL DEFAULT '', when_to_use TEXT NOT NULL DEFAULT '', when_not_to_use TEXT NOT NULL DEFAULT '', instructions TEXT NOT NULL DEFAULT '', success_criteria TEXT NOT NULL DEFAULT '[]', scope VARCHAR(32) NOT NULL, status VARCHAR(32) NOT NULL, priority INTEGER NOT NULL DEFAULT 0, current_version INTEGER NOT NULL DEFAULT 1, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS idx_skills_global_slug ON skills(slug) WHERE scope='global';
CREATE UNIQUE INDEX IF NOT EXISTS idx_skills_workspace_slug ON skills(slug,workspace_id) WHERE scope='workspace';
CREATE UNIQUE INDEX IF NOT EXISTS idx_skills_project_slug ON skills(slug,workspace_id,project_id) WHERE scope='project';
CREATE INDEX IF NOT EXISTS idx_skills_lookup ON skills(status,scope,workspace_id,project_id,priority);
CREATE TABLE IF NOT EXISTS skill_domains (skill_id VARCHAR(36) NOT NULL REFERENCES skills(id) ON DELETE CASCADE, value VARCHAR(191) NOT NULL, PRIMARY KEY(skill_id,value));
CREATE TABLE IF NOT EXISTS skill_intents (LIKE skill_domains INCLUDING ALL); ALTER TABLE skill_intents ADD CONSTRAINT fk_skill_intents_skill FOREIGN KEY(skill_id) REFERENCES skills(id) ON DELETE CASCADE;
CREATE TABLE IF NOT EXISTS skill_object_types (LIKE skill_domains INCLUDING ALL); ALTER TABLE skill_object_types ADD CONSTRAINT fk_skill_object_types_skill FOREIGN KEY(skill_id) REFERENCES skills(id) ON DELETE CASCADE;
CREATE TABLE IF NOT EXISTS skill_tags (LIKE skill_domains INCLUDING ALL); ALTER TABLE skill_tags ADD CONSTRAINT fk_skill_tags_skill FOREIGN KEY(skill_id) REFERENCES skills(id) ON DELETE CASCADE;
CREATE TABLE IF NOT EXISTS skill_keywords (LIKE skill_domains INCLUDING ALL); ALTER TABLE skill_keywords ADD CONSTRAINT fk_skill_keywords_skill FOREIGN KEY(skill_id) REFERENCES skills(id) ON DELETE CASCADE;
CREATE TABLE IF NOT EXISTS skill_capabilities (LIKE skill_domains INCLUDING ALL); ALTER TABLE skill_capabilities ADD CONSTRAINT fk_skill_capabilities_skill FOREIGN KEY(skill_id) REFERENCES skills(id) ON DELETE CASCADE;
CREATE TABLE IF NOT EXISTS skill_compatibility (LIKE skill_domains INCLUDING ALL); ALTER TABLE skill_compatibility ADD CONSTRAINT fk_skill_compatibility_skill FOREIGN KEY(skill_id) REFERENCES skills(id) ON DELETE CASCADE;
CREATE TABLE IF NOT EXISTS skill_steps (id VARCHAR(36) PRIMARY KEY, skill_id VARCHAR(36) NOT NULL REFERENCES skills(id) ON DELETE CASCADE, position INTEGER NOT NULL, title VARCHAR(255) NOT NULL, instruction TEXT NOT NULL, condition_text TEXT NULL, is_required BOOLEAN NOT NULL, expected_result TEXT NULL, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL, UNIQUE(skill_id,position));
CREATE TABLE IF NOT EXISTS skill_tools (id VARCHAR(36) PRIMARY KEY, skill_id VARCHAR(36) NOT NULL REFERENCES skills(id) ON DELETE CASCADE, tool_name VARCHAR(191) NOT NULL, tool_namespace VARCHAR(191) NULL, requirement VARCHAR(32) NOT NULL, purpose TEXT NOT NULL DEFAULT '', usage_hint TEXT NULL);
CREATE TABLE IF NOT EXISTS skill_context_requirements (id VARCHAR(36) PRIMARY KEY, skill_id VARCHAR(36) NOT NULL REFERENCES skills(id) ON DELETE CASCADE, type VARCHAR(64) NOT NULL, query_text TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', required BOOLEAN NOT NULL, priority INTEGER NOT NULL DEFAULT 0, max_tokens INTEGER NULL);
CREATE TABLE IF NOT EXISTS skill_dependencies (id VARCHAR(36) PRIMARY KEY, skill_id VARCHAR(36) NOT NULL REFERENCES skills(id) ON DELETE CASCADE, depends_on_skill_id VARCHAR(36) NOT NULL REFERENCES skills(id), type VARCHAR(32) NOT NULL, position INTEGER NOT NULL DEFAULT 0, UNIQUE(skill_id,depends_on_skill_id,type));
CREATE TABLE IF NOT EXISTS skill_examples (id VARCHAR(36) PRIMARY KEY, skill_id VARCHAR(36) NOT NULL REFERENCES skills(id) ON DELETE CASCADE, title VARCHAR(255) NOT NULL, input_example TEXT NOT NULL, expected_behavior TEXT NOT NULL, bad_behavior TEXT NULL, priority INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS skill_versions (id VARCHAR(36) PRIMARY KEY, skill_id VARCHAR(36) NOT NULL REFERENCES skills(id) ON DELETE CASCADE, version INTEGER NOT NULL, snapshot TEXT NOT NULL, change_summary TEXT NOT NULL DEFAULT '', created_by VARCHAR(191) NULL, created_at VARCHAR(40) NOT NULL, UNIQUE(skill_id,version));
CREATE TABLE IF NOT EXISTS skill_executions (id VARCHAR(36) PRIMARY KEY, skill_id VARCHAR(36) NOT NULL REFERENCES skills(id), skill_version INTEGER NOT NULL, workspace_id VARCHAR(36) NULL, project_id VARCHAR(36) NULL, agent_id VARCHAR(191) NULL, model_provider VARCHAR(191) NULL, model_name VARCHAR(191) NULL, task_summary TEXT NOT NULL, task_hash VARCHAR(191) NULL, started_at VARCHAR(40) NOT NULL, finished_at VARCHAR(40) NULL, duration_ms BIGINT NULL, status VARCHAR(32) NOT NULL, success BOOLEAN NOT NULL, tool_calls_count INTEGER NULL, input_tokens INTEGER NULL, output_tokens INTEGER NULL, error_type VARCHAR(191) NULL, error_message TEXT NULL, feedback TEXT NULL, created_at VARCHAR(40) NOT NULL);
CREATE INDEX IF NOT EXISTS idx_executions_skill_model ON skill_executions(skill_id,model_provider,model_name,success);
CREATE TABLE IF NOT EXISTS skill_proposals (id VARCHAR(36) PRIMARY KEY, skill_id VARCHAR(36) NOT NULL REFERENCES skills(id), base_version INTEGER NOT NULL, proposed_snapshot TEXT NOT NULL, summary TEXT NOT NULL DEFAULT '', status VARCHAR(32) NOT NULL, created_by VARCHAR(191) NULL, reviewed_by VARCHAR(191) NULL, review_note TEXT NULL, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL, reviewed_at VARCHAR(40) NULL);
CREATE INDEX IF NOT EXISTS idx_skill_proposals_status ON skill_proposals(status,skill_id,created_at);
CREATE TABLE IF NOT EXISTS execution_events (id VARCHAR(36) PRIMARY KEY, execution_id VARCHAR(36) NOT NULL REFERENCES skill_executions(id) ON DELETE CASCADE, position INTEGER NOT NULL, event_type VARCHAR(191) NOT NULL, event_data TEXT NOT NULL DEFAULT '', created_at VARCHAR(40) NOT NULL, UNIQUE(execution_id,position));
